def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    from collections import Counter

    # Locate rectangular outlines: a color must form all four straight sides.
    frames = []
    colors = set(v for row in grid for v in row if v)
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1 + 1)) and \
           all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1 + 1)):
            frames.append((r0, r1, c0, c1, color))

    # Count isolated non-frame colors; their counts describe the checker pattern
    # to be painted inside the outlines.
    frame_cells = {(r, c) for r0, r1, c0, c1, _ in frames
                   for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)}
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] and (r, c) not in frame_cells)
    candidates = [(n, color) for color, n in counts.items()]

    # Remove the scattered marks outside the outlines.
    for r in range(h):
        for c in range(w):
            if (r, c) not in frame_cells:
                g[r][c] = 0

    used = set()
    for r0, r1, c0, c1, border in frames:
        # The examples use a checkerboard, beginning with a mark in the
        # upper-left interior cell. Choose the scattered color with matching
        # count, if available.
        nr, nc = r1-r0-1, c1-c0-1
        target = (nr * nc + 1) // 2
        options = [(abs(n-target), color, n) for n, color in candidates
                   if color != border and color not in used]
        if options:
            _, color, n = min(options)
            used.add(color)
        else:
            color = candidates[0][1] if candidates else 1
        for r in range(r0+1, r1):
            for c in range(c0+1, c1):
                if (r-r0-1 + c-c0-1) % 2 == 0:
                    g[r][c] = color
    return g
